<?php
require_once '../../config/auth.php';
requestMethod('GET');
requireAdmin();
try{ $db=getDB(); $where=[]; $params=[]; if(!empty($_GET['category'])){$where[]='r.category=?';$params[]=$_GET['category'];} if(!empty($_GET['status'])){$where[]='r.status=?';$params[]=$_GET['status'];} if(!empty($_GET['search'])){$q='%'.trim($_GET['search']).'%';$where[]='(r.title LIKE ? OR r.description LIKE ? OR u.full_name LIKE ?)';array_push($params,$q,$q,$q);} $whereSql=$where?'WHERE '.implode(' AND ',$where):''; $stmt=$db->prepare("SELECT r.*, u.full_name AS reported_by, u.email AS reporter_email FROM reports r LEFT JOIN users u ON u.id=r.reported_by_user_id $whereSql ORDER BY r.created_at DESC"); $stmt->execute($params); $reports=array_map(fn($r)=>['id'=>(int)$r['id'],'reported_by_user_id'=>$r['reported_by_user_id']?(int)$r['reported_by_user_id']:null,'reported_by'=>$r['reported_by'],'reporter_email'=>$r['reporter_email'],'category'=>$r['category'],'title'=>$r['title'],'description'=>$r['description'],'image_path'=>$r['image_path'],'reference_id'=>$r['reference_id']?(int)$r['reference_id']:null,'status'=>$r['status'],'admin_reply'=>$r['admin_reply'],'replied_at'=>$r['replied_at'],'created_at'=>$r['created_at']],$stmt->fetchAll()); jsonResponse(['success'=>true,'reports'=>$reports]); }catch(Throwable $e){ jsonError('Could not fetch reports.',500); }
